  749: /// Compress the partial into `<stem>.jsonl.gz` — through a temp file and one
  750: /// rename, so a reader or a crash sees either no finished log or a whole
  751: /// one — then remove the partial. The finished log keeps the partial's
  752: /// modified time, so pruning orders a recovered log by when its run wrote.
  753: fn compress_into_place(dir: &Path, stem: &str) -> io::Result<PathBuf> {
  754:     let partial = path_of(dir, stem, PARTIAL_SUFFIX);
  755:     let temp = path_of(dir, stem, TEMP_SUFFIX);
  756:     let finished = path_of(dir, stem, FINISHED_SUFFIX);
  757:     if let Err(error) = write_compressed(&partial, &temp, &finished) {
  758:         let _ = fs::remove_file(&temp);
  759:         return Err(error);
  760:     }
  761:     sync_dir(dir);
  762:     // The finished log is whole now; a partial left by a failure here is
  763:     // removed by `recover`.
  764:     if let Err(error) = fs::remove_file(&partial) {
  765:         log::warn!(
  766:             "job logs: could not remove {} after finishing it: {error}",
  767:             partial.display()
  768:         );
  769:     }
  770:     Ok(finished)
  771: }
