  773: fn write_compressed(partial: &Path, temp: &Path, finished: &Path) -> io::Result<()> {
  774:     let mut input = File::open(partial)?;
  775:     let modified = input.metadata()?.modified()?;
  776:     let mut encoder = GzEncoder::new(BufWriter::new(File::create(temp)?), Compression::fast());
  777:     io::copy(&mut input, &mut encoder)?;
  778:     let output = encoder
  779:         .finish()?
  780:         .into_inner()
  781:         .map_err(|error| error.into_error())?;
  782:     output.set_modified(modified)?;
  783:     output.sync_all()?;
  784:     drop(output);
  785:     fs::rename(temp, finished)
